#include <bits/stdc++.h>
#define endl "\n"
#define ll long long
#define sz(v) ((int)((v).size()))
using namespace std;

int cnt, n;
string g, ans;
vector<string> v;
vector<int> bulls, cows;

bool valid() {
    for (int j = 0; j < n; ++j) {
        int bull = 0, cow = 0;

        for (int i = 0; i < 4; ++i) {
            if (v[j][i] == g[i])
                ++bull;
        }

        for (int i = 0; i < 4; ++i) {
            if (g.find(v[j][i]) != string::npos)
                ++cow;
        }

        cow -= bull;
        if (bull != bulls[j] || cow != cows[j])
            return false;
    }
    return true;
}

void solve(int i) {
    if (i == 4) {
        if (valid()) {
            ++cnt;
            ans = g;
        }
        return;
    }

    for (char digit = '0'; digit <= '9'; ++digit) {
        if (g.find(digit) != string::npos)
            continue;

        g.push_back(digit);
        solve(i + 1);
        g.pop_back();
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    for (int i = 0; i < n; ++i) {
        string num;
        int b, c;
        cin >> num >> b >> c;
        v.push_back(num);
        bulls.push_back(b);
        cows.push_back(c);
    }

    solve(0);

    if (cnt == 0)
        cout << "Incorrect data\n";
    else if (cnt == 1)
        cout << ans << '\n';
    else
        cout << "Need more data\n";

    return 0;
}

